/*
 * A169071  Number of reduced words of length n in Coxeter group on 10
 *          generators S_i with relations (S_i)^2 = (S_i S_j)^25 = I.
 * https://oeis.org/A169071
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = number of reduced words of length n in the Coxeter group
 *            generated by 10 involutions S_i with relations S_i^2 =
 *            (S_iS_j)^25 = 1. The sequence satisfies the linear recurrence
 *            derived from its generating function: a(0) = 1 for 1 ≤ n ≤ 25:
 *            a(n) = q(n) + 8 * Σ_{k=1}^{n} a(n-k) where q(0)=1, q(...
 * Range:     u8 n <= 2, u16 n <= 4, u32 n <= 10, u64 n <= 18, u128 n <= 18,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)1;

    /* Allocate array for terms up to n.  n is expected to be small enough
       that a linear allocation of size n+1 is feasible. */
    size_t N = (size_t)n;
    seq_t *buf = (seq_t *)malloc((N + 1) * sizeof(seq_t));
    if (!buf)
        return (seq_t)0;  /* allocation failure */

    buf[0] = (seq_t)1;

    for (size_t i = 1; i <= N; ++i)
    {
        seq_t sum = (seq_t)0;

        /* Add 8 * a[i-k] for k = 1 … min(24, i) */
        size_t up = (i < 24 ? i : 24);
        for (size_t k = 1; k <= up; ++k)
            sum += (seq_t)8 * buf[i - k];

        /* If i ≥ 25, subtract 36 * a[i-25] */
        if (i >= 25)
            sum -= (seq_t)36 * buf[i - 25];

        /* Add the inhomogeneous term q(i) for i ≤ 25 */
        seq_t q_val = (seq_t)0;
        if (i <= 25)
        {
            if (i <= 24)
                q_val = (seq_t)2;
            else              /* i == 25 */
                q_val = (seq_t)1;
        }
        buf[i] = sum + q_val;
    }

    seq_t result = buf[N];
    free(buf);
    return result;
}
